/bin/bash -lc "cat > src/server.js <<'EOF'
import { createServer } from 'node:http';
import { parse as parseUrl } from 'node:url';
import { resolve } from 'node:path';

import { BookStore } from './book-store.js';

const PORT = process.env.PORT ? Number(process.env.PORT) : 3000;
const DATA_FILE = resolve(process.cwd(), 'data/books.json');

const store = new BookStore(DATA_FILE);

const server = createServer(async (req, res) => {
  try {
    const { pathname = '/' } = parseUrl(req.url ?? '/', true);

    if (req.method === 'GET' && pathname === '/') {
      const books = await store.listBooks();
      return sendHtml(res, renderHomePage(books));
    }

    if (req.method === 'POST' && pathname === '/books') {
      const form = await readFormBody(req);
      const title = (form.get('title') ?? '').toString().trim();
      const author = (form.get('author') ?? '').toString().trim();
      const notes = (form.get('notes') ?? '').toString().trim();

      if ("'!title || !author) {
        return redirect(res, '"'/?error=missing_required_fields');
      }

      await store.addBook({ title, author, notes });
      return redirect(res, '/');
    }

    if (req.method === 'GET' && pathname.startsWith('/books/')) {
      const id = decodeURIComponent(pathname.replace('/books/', ''));
      const book = await store.getBookById(id);

      if ("'!book) {
        return notFound(res);
      }

      return sendHtml(res, renderBookPage(book));
    }

    if (req.method === '"'POST' && pathname.startsWith('/books/') && pathname.endsWith('/finish')) {
      const id = decodeURIComponent(pathname.replace('/books/', '').replace('/finish', ''));
      const book = await store.markFinished(id);

      if ("'!book) {
        return notFound(res);
      }

      return redirect(res, '"'/');
    }

    return notFound(res);
  } catch (error) {
    console.error(error);
    return sendHtml(
      res,
      renderShell('Server Error', '<p>Something went wrong. Please try again.</p>'),
      500
    );
  }
});

server.listen(PORT, () => {
  console.log("'`Book tracker running at http://localhost:${PORT}`);
});

function sendHtml(res, html, statusCode = 200) {
  res.statusCode = statusCode;
  res.setHeader('"'Content-Type', 'text/html; charset=utf-8');
  res.end(html);
}

function redirect(res, location) {
  res.statusCode = 303;
  res.setHeader('Location', location);
  res.end();
}

function notFound(res) {
  return sendHtml(res, renderShell('Not Found', '<p>Book not found.</p><p><a href=\"/\">Back home</a></p>'), 404);
}

async function readFormBody(req) {
  const chunks = [];

  for await (const chunk of req) {
    chunks.push(typeof chunk === 'string' ? Buffer.from(chunk) : chunk);
  }

  const body = Buffer.concat(chunks).toString('utf-8');
  return new URLSearchParams(body);
}

function renderHomePage(books) {
  const reading = books.filter((book) => book.status "'!== '"'finished');
  const finished = books.filter((book) => book.status === 'finished');

  return renderShell(
    'Book Tracker',
    "'`
      <section>
        <h1>Book Tracker</h1>
        <p>Track what you'"'re reading and what you've finished.</p>
      </section>

      <section>
        <h2>Add a Book</h2>
        <form method=\"post\" action=\"/books\">
          <label>
            Title
            <input name=\"title\" required />
          </label>
          <label>
            Author
            <input name=\"author\" required />
          </label>
          <label>
            Notes
            <textarea name=\"notes\" rows=\"4\" placeholder=\"Optional notes\"></textarea>
          </label>
          <button type=\"submit\">Add Book</button>
        </form>
      </section>

      <section>
        <h2>Currently Reading</h2>
        "'${renderBookList(reading, { showFinishButton: true })}
      </section>

      <section>
        <h2>Finished</h2>
        ${renderBookList(finished, { showFinishButton: false })}
      </section>
    `
  );
}

function renderBookPage(book) {
  const notes = book.notes?.trim() ? escapeHtml(book.notes) : '"'No notes yet.';
  const statusLabel = book.status === 'finished' ? 'Finished' : 'Currently reading';

  return renderShell(
    "'`${escapeHtml(book.title)} · Book Tracker`,
    `
      <section>
        <p><a href="/">← Back to all books</a></p>
        <h1>${escapeHtml(book.title)}</h1>
        <p><strong>Author:</strong> ${escapeHtml(book.author)}</p>
        <p><strong>Status:</strong> ${statusLabel}</p>
        <p><strong>Notes:</strong></p>
        <p class="notes">${notes.replaceAll('"'\\n', '<br />')}</p>
      </section>
    "'`
  );
}

function renderBookList(books, { showFinishButton }) {
  if (books.length === 0) {
    return '"'<p class=\"empty\">No books here yet.</p>';
  }

  return "'`
    <ul>
      ${books
        .map((book) => {
          const title = escapeHtml(book.title);
          const author = escapeHtml(book.author);
          const detailLink = `/books/${encodeURIComponent(book.id)}`;

          const finishButton = showFinishButton
            ? `
              <form method="post" action="${detailLink}/finish">
                <button type="submit">Mark finished</button>
              </form>
            `
            : '"'';

          return "'`
            <li>
              <div>
                <a href="${detailLink}">${title}</a>
                <span>by ${author}</span>
              </div>
              ${finishButton}
            </li>
          `;
        })
        .join('"'')}
    </ul>
  "'`;
}

function renderShell(pageTitle, content) {
  return `
    <!doctype html>
    <html lang="en">
      <head>
        <meta charset="utf-8" />
        <meta name="viewport" content="width=device-width, initial-scale=1" />
        <title>${pageTitle}</title>
        <style>
          body {
            font-family: system-ui, sans-serif;
            max-width: 760px;
            margin: 2rem auto;
            padding: 0 1rem 2rem;
            line-height: 1.4;
            color: #202124;
          }

          h1,
          h2 {
            margin-bottom: 0.5rem;
          }

          section {
            margin-bottom: 2rem;
            padding-bottom: 1rem;
            border-bottom: 1px solid #ddd;
          }

          form {
            display: grid;
            gap: 0.75rem;
            max-width: 420px;
          }

          label {
            display: grid;
            gap: 0.35rem;
          }

          input,
          textarea,
          button {
            font: inherit;
            padding: 0.45rem 0.55rem;
          }

          ul {
            list-style: none;
            padding: 0;
            margin: 0;
            display: grid;
            gap: 0.85rem;
          }

          li {
            border: 1px solid #ddd;
            border-radius: 6px;
            padding: 0.75rem;
            display: flex;
            align-items: center;
            justify-content: space-between;
            gap: 0.75rem;
          }

          li div {
            display: grid;
            gap: 0.25rem;
          }

          li span {
            color: #555;
          }

          .empty {
            color: #666;
          }

          .notes {
            white-space: normal;
          }
        </style>
      </head>
      <body>
        ${content}
      </body>
    </html>
  `;
}

function escapeHtml(value) {
  return value
    .replaceAll('"'&', '&amp;')
    .replaceAll('<', '&lt;')
    .replaceAll('>', '&gt;')
    .replaceAll('\"', '&quot;')
    .replaceAll(\"'\", '&#039;');
}
EOF"

